mapper.select:
select w.id, w.corpid, r.customer_id, w.writeoff_no, w.receipt_id, w.receivable_id, w.writeoff_date,
    w.amount, w.status, w.reversed_time, w.remark, w.creator_id, w.modify_id
from receipt_writeoff w join receipt r on r.id = w.receipt_id and r.corpid = w.corpid
where w.corpid = #{conditionMap.corpid} and w.del = 0
and receipt_id = #{conditionMap.receiptId}
and receivable_id = #{conditionMap.receivableId}
order by id desc
limit #{conditionMap.offset}, #{conditionMap.limit}

mapper.update:
update receipt_writeoff
set status = 0, reversed_time = #{reversedTime}, modify_id = #{userId}, update_time = #{reversedTime}
where corpid = #{corpid} and id = #{id} and del = 0 and status = 1
